import type { AnchorHTMLAttributes, HTMLAttributes, LiHTMLAttributes, Ref } from "react";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

export type BreadcrumbProps = HTMLAttributes<HTMLElement>;

/** A trail of ancestors ending at the current page. Separators are drawn by CSS, so they are never read aloud. */
export function Breadcrumb({ className, children, ...rest }: BreadcrumbProps) {
  return (
    <nav aria-label="Breadcrumb" {...rest} className={cx("hm-breadcrumb", className)}>
      <ol className="hm-breadcrumb-list">{children}</ol>
    </nav>
  );
}

export function BreadcrumbItem({ className, ...rest }: LiHTMLAttributes<HTMLLIElement>) {
  return <li {...rest} className={cx("hm-breadcrumb-item", className)} />;
}

export function BreadcrumbLink({
  asChild,
  className,
  ...rest
}: AnchorHTMLAttributes<HTMLAnchorElement> & { asChild?: boolean; ref?: Ref<HTMLAnchorElement> }) {
  const Comp = asChild ? Slot : "a";
  return <Comp {...(rest as object)} className={cx("hm-breadcrumb-link", className)} />;
}

/** The current page: plain text with `aria-current="page"`. */
export function BreadcrumbPage({ className, ...rest }: HTMLAttributes<HTMLSpanElement>) {
  return <span {...rest} aria-current="page" className={cx("hm-breadcrumb-page", className)} />;
}
